import{$ as e,B as t,et as n,pt as r}from"./chunks/framework.KBYRAceO.js";import"./chunks/assets.C6yW3bU8.js";var i=JSON.parse(`{"title":"AWS 웹 콘솔 로그인 시 기본 리전","description":"웹 콘솔 로그인 시 다른 리전으로 이동된다면 자주 사용하는 리전을 고정하는 것을 알아봅니다.","frontmatter":{"title":"AWS 웹 콘솔 로그인 시 기본 리전","date":"2026-05-17T13:45+09:00","description":"웹 콘솔 로그인 시 다른 리전으로 이동된다면 자주 사용하는 리전을 고정하는 것을 알아봅니다.","tags":["AWS","Web Console"]},"headers":[],"relativePath":"posts/aws-console-default-region.md","filePath":"posts/aws-console-default-region.md","lastUpdated":1787354858000}`),a={name:`posts/aws-console-default-region.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="aws-웹-콘솔-로그인-시-기본-리전" tabindex="-1">AWS 웹 콘솔 로그인 시 기본 리전 <a class="header-anchor" href="#aws-웹-콘솔-로그인-시-기본-리전" aria-label="Permalink to “AWS 웹 콘솔 로그인 시 기본 리전”">​</a></h1><p>AWS 웹 콘솔 로그인 후 개발 (Dev) 이나 운영 (Prod) 환경으로 역할 전환 (Switch Role) 을 마쳤는데, 분명 존재해야 할 인프라 리소스가 보이지 않아 당황했던 경험이 있으실 겁니다.</p><p>저희와 같은 국내 기업은 인프라의 특성상 대부분 <strong>서울 (ap-northeast-2)</strong> 리전 하나만을 사용합니다. 그럼에도 불구하고 로그인 또는 역할 전환 시 전혀 사용할 일이 없는 북유럽의 <strong>스톡홀름 (eu-north-1)</strong> 리전으로 강제 리다이렉트되는 문제가 종종 발생하여 불필요한 번거로움을 유발합니다.</p><p>이렇듯 사용하지 않는 리전으로 이동되는 문제를 예방하기 위해 <mark>사용자 통합 설정 (Unified Settings)</mark> 의 기본 리전을 설정하여 고정할 수 있습니다.</p><h2 id="_1-스톡홀름-리전으로-리다이렉트된-이유" tabindex="-1">1. 스톡홀름 리전으로 리다이렉트된 이유 <a class="header-anchor" href="#_1-스톡홀름-리전으로-리다이렉트된-이유" aria-label="Permalink to “1. 스톡홀름 리전으로 리다이렉트된 이유”">​</a></h2><p>스톡홀름 리전으로 이동되는 명확한 이유는 아쉽게도 찾을 수 없었습니다. 다만, 해당 문제가 발생한 모든 사용자의 설정을 확인해 본 결과, 공통적으로 사용자 통합 설정 내 기본 리전 항목이 초기 기본값(Default)인 <mark>마지막으로 사용한 리전 (Last used Region)</mark> 으로 지정되어 있었습니다.</p><p>웹 콘솔 화면을 다시 보니 브라우저 주소에 <strong><code>region</code></strong> 정보가 포함되어 작동하고 있었습니다. 평소에 서울 리전을 기준으로 웹 콘솔을 정상적으로 이용할 때는 주소가 <strong><code>https://ap-northeast-2.console.aws.amazon.com</code></strong> 형식으로 유지되거나 <code>?region=ap-northeast-2</code> 와 같은 파라미터가 명시되어 붙어 다닙니다.</p><p>평소에 <strong><code>https://aws.amazon.com/ko/console/</code></strong> 주소로 접속해 우측 상단의 <strong>[콘솔에 로그인]</strong> 버튼을 눌러 로그인 화면으로 이동하는 지극히 평범한 경로를 거칠 경우, 최초 진입 단계부터 <code>region</code> 파라미터가 포함되어 있지 않습니다. 실제로 로그인 절차나 역할 전환을 진행하는 과정에서 브라우저 주소창을 유심히 살펴보면, 중간에 <strong><code>https://ap-southeast-2.signin.aws.amazon.com/</code></strong> 과 같이 전혀 상관없는 해외 리전의 로그인 전용 (signin) 도메인을 거쳐서 라우팅되는 것을 확인할 수 있습니다.</p><p><img src="/images/posts/aws-console-default-region/001.png" alt="공식 포털의 콘솔 로그인 진입 경로" loading="lazy"></p><p>기본 설정이 <mark>마지막으로 사용한 리전</mark> 으로 세팅되어 있다면, 포털의 콘솔 로그인 버튼을 경유해 로그인하거나 역할을 바꿀 때 브라우저 세션이나 AWS 로그인 프로세스 내부에서 &#39;마지막으로 사용한 리전&#39; 정보를 성공적으로 읽어와 정상적으로 인도해 주어야 맞습니다. 하지만 실제로는 로그인 절차나 역할 전환 도중에 마지막으로 사용된 리전 값을 정상적으로 불러오지 못하고 유실하는 상황이 발생하는 것으로 추정됩니다.</p><p>이렇게 마지막 리전 정보를 제대로 가져오지 못한 상태라면, 보통 AWS의 글로벌 서비스 (IAM, Route 53, 결제 등) 가 메인 엔드포인트로 삼는 <strong>버지니아 북부 (us-east-1)</strong> 등으로 진입할 것이라 예상하기 쉽습니다. 그러나 AWS의 모호한 내부 라우팅 한계로 인해 전혀 연고가 없는 스톡홀름 리전으로 튕겨 나가게 되는 것입니다. 그래서 해결책으로 <mark>사용자 통합 설정 (Unified Settings)</mark> 에 들어가서 기본으로 사용하는 리전을 서울 리전으로 고정해 두는 것이 확실하게 도움이 됩니다.</p><h2 id="_2-통합-설정에서-기본-리전-지정하기" tabindex="-1">2. 통합 설정에서 기본 리전 지정하기 <a class="header-anchor" href="#_2-통합-설정에서-기본-리전-지정하기" aria-label="Permalink to “2. 통합 설정에서 기본 리전 지정하기”">​</a></h2><p>만약 현재 저희 조직과 같이 사용 중인 리전이 그리 다양하지 않고 대부분 <strong>서울 (ap-northeast-2)</strong> 리전 위주로 인프라가 운영된다면, 로그인할 때마다 매번 수동으로 리전을 변경해야 하는 작업은 대단히 번거롭습니다.</p><p>이때 웹 콘솔 우측 상단의 <strong>톱니바퀴 (기어) 아이콘 (⚙)</strong> 을 누르면 제공되는 <strong>모든 사용자 설정 보기 (See all user settings)</strong> 링크를 통해 <mark>사용자 통합 설정 (Unified Settings)</mark> 으로 바로 진입할 수 있으며, 여기서 기본 리전을 서울 리전으로 고정해 두는 것이 확실하게 도움이 됩니다.</p><p>기본 리전을 서울 (ap-northeast-2) 리전으로 지정해 두면, 로그인 화면에서 로그인 전용 (signin) 주소가 서로 다르게 잡혀 있더라도 로그인 및 역할 전환 (Switch Role) 이 완료되는 즉시 고정해 둔 서울 리전인 <mark><code>https://ap-northeast-2.console.aws.amazon.com/console/home</code></mark> 주소로 자동 리다이렉트됩니다.</p><h3 id="설정-방법" tabindex="-1">설정 방법 <a class="header-anchor" href="#설정-방법" aria-label="Permalink to “설정 방법”">​</a></h3><ol><li><p>AWS 웹 콘솔에 로그인합니다.</p></li><li><p>상단 네비게이션 바 오른쪽 끝에 있는 <strong>톱니바퀴 아이콘 (⚙)</strong> 을 클릭합니다.</p></li><li><p>드롭다운 메뉴에서 <strong>모든 사용자 설정 보기 (See all user settings)</strong> 를 클릭합니다.</p><p><img src="/images/posts/aws-console-default-region/002.png" alt="모든 사용자 설정 보기" loading="lazy"></p></li><li><p><strong>현지화 및 기본 리전 (Localization and default Region)</strong> 항목에서 <strong>편집 (Edit)</strong> 버튼을 누릅니다.</p></li><li><p><strong>기본 리전 (Default Region)</strong> 드롭다운 메뉴에서 주로 사용하는 리전 (예: <strong>서울 (ap-northeast-2)</strong> ) 을 선택합니다.</p></li><li><p><strong>설정 저장 (Save settings)</strong> 을 클릭합니다.</p><p><img src="/images/posts/aws-console-default-region/003.png" alt="기본 리전 설정 완료" loading="lazy"></p></li></ol><h2 id="_3-역할-전환-switch-role-시-기본-리전-대처-팁" tabindex="-1">3. 역할 전환(Switch Role) 시 기본 리전 대처 팁 <a class="header-anchor" href="#_3-역할-전환-switch-role-시-기본-리전-대처-팁" aria-label="Permalink to “3. 역할 전환(Switch Role) 시 기본 리전 대처 팁”">​</a></h2><p>특히 <mark>페더레이션 사용자 (Federated User)</mark> 로서 하나의 중심 연동 계정을 거쳐 로그인한 뒤, 개발 (Dev), 검증 (Staging), 운영 (Prod) 등 <strong>환경별로 역할을 나누어 인프라를 관리하는 구조</strong> 라면 실무에서 하루에도 수없이 <mark>역할 전환 (Switch Role)</mark> 과정을 거치게 됩니다.</p><h3 id="팁-1-url-북마크-활용하기" tabindex="-1">팁 1: URL 북마크 활용하기 <a class="header-anchor" href="#팁-1-url-북마크-활용하기" aria-label="Permalink to “팁 1: URL 북마크 활용하기”">​</a></h3><p>역할 전환 후 항상 특정 리전의 콘솔 화면으로 바로 진입하고 싶다면, 브라우저 북마크에 리전 정보가 포함된 URL을 등록해 두고 전환 후 클릭하는 방법이 가장 단순하고 확실합니다.</p><ul><li>예: 서울 리전 콘솔 홈 주소 <code>https://ap-northeast-2.console.aws.amazon.com/console/home?region=ap-northeast-2</code></li></ul><h3 id="팁-2-브라우저-확장-프로그램-활용하기-aws-extend-switch-roles" tabindex="-1">팁 2: 브라우저 확장 프로그램 활용하기 (<code>aws-extend-switch-roles</code>) <a class="header-anchor" href="#팁-2-브라우저-확장-프로그램-활용하기-aws-extend-switch-roles" aria-label="Permalink to “팁 2: 브라우저 확장 프로그램 활용하기 (aws-extend-switch-roles)”">​</a></h3><p>만약 브라우저 확장 프로그램인 <strong><a href="https://github.com/tilfin/aws-extend-switch-roles" target="_blank" rel="noreferrer">aws-extend-switch-roles</a></strong> 를 이미 사용 중이거나 도입할 예정이라면, 마치 AWS CLI 프로필에 기본 리전을 설정해 사용하는 것처럼 설정 파일(<code>config</code>)의 프로필 정보에 <mark><code>region</code> 설정을 명시적으로 포함할 것</mark> 을 강력히 권장합니다.</p><div class="vp-code-block-title"><div class="vp-code-block-title-bar"><span class="vp-code-block-title-text" data-title="aws-extend-switch-roles 설정 예시">aws-extend-switch-roles 설정 예시</span></div><div class="language-ini"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[profile my-dev-role]</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">role_arn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = arn:aws:iam::123456789012:role/DeveloperRole</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">source_profile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = default</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">color</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 27ae60</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">region</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = ap-northeast-2</span></span></code></pre></div></div><p>설정 파일에 <code>region</code> 설정을 적어두면 해당 역할로 전환하는 즉시 지정한 서울 리전 콘솔 화면으로 자동 연결되어 매우 편리합니다.</p><p>감사합니다.</p>`,27)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};